public class FaultRouterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object status(Runnable action) {
        try {
            return FaultRouter.statusFor(action);
        } catch (Throwable crash) {
            return "statusFor threw " + crash.getClass().getSimpleName();
        }
    }

    static Object described(Runnable action) {
        try {
            return FaultRouter.describe(action);
        } catch (Throwable crash) {
            return "describe threw " + crash.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("a clean action is 200", 200, status(() -> { }));
        check("a missing record is 404", 404, status(() -> { throw new NotFoundFault("user"); }));
        check("bad input is 400", 400, status(() -> { throw new BadInputFault("email"); }));
        check("too many requests is 429", 429, status(() -> { throw new RateLimitFault(); }));
        check("an unexpected runtime failure is 500", 500,
                status(() -> { throw new IllegalArgumentException("boom"); }));
        check("describe on success", "200 OK", described(() -> { }));
        check("describe on a known fault", "404 NotFoundFault: user not found",
                described(() -> { throw new NotFoundFault("user"); }));
        check("describe on an unexpected failure", "500 IllegalArgumentException: boom",
                described(() -> { throw new IllegalArgumentException("boom"); }));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

